<dialog class="vc-dialog" id="coupon-dialog"><div class="vc-dialog-head"><h2>Create coupon</h2><button type="button" class="vc-btn small" data-close-dialog>Close</button></div><form class="vc-dialog-body" data-frontend-form="coupon" data-success="Coupon rules validated in the frontend preview."><div class="vc-form-grid"><div class="vc-field"><label for="vc-promotions-input-1">Coupon code</label><input name="vc-promotions-input-1" id="vc-promotions-input-1" class="vc-input" required pattern="[A-Z0-9_-]{4,20}" maxlength="20" placeholder="FESTIVE20"></div><div class="vc-field"><label for="vc-promotions-select-2">Discount type</label><select name="vc-promotions-select-2" id="vc-promotions-select-2" class="vc-select" required><option>Percentage</option><option>Fixed amount</option><option>Free standard delivery</option></select></div><div class="vc-field"><label for="vc-promotions-input-3">Discount value</label><input name="vc-promotions-input-3" id="vc-promotions-input-3" class="vc-input" type="number" data-money min="0" max="100000" required></div><div class="vc-field"><label for="vc-promotions-input-4">Minimum order</label><input name="vc-promotions-input-4" id="vc-promotions-input-4" class="vc-input" type="number" data-money min="0" max="10000000" required></div><div class="vc-field"><label for="vc-promotions-input-5">Start</label><input name="vc-promotions-input-5" id="vc-promotions-input-5" class="vc-input" type="datetime-local" required></div><div class="vc-field"><label for="vc-promotions-input-6">End</label><input name="vc-promotions-input-6" id="vc-promotions-input-6" class="vc-input" type="datetime-local" required></div><div class="vc-field"><label for="vc-promotions-input-7">Total usage limit</label><input name="vc-promotions-input-7" id="vc-promotions-input-7" class="vc-input" type="number" min="1" max="1000000" required></div><div class="vc-field"><label for="vc-promotions-input-8">Per-customer limit</label><input name="vc-promotions-input-8" id="vc-promotions-input-8" class="vc-input" type="number" min="1" max="100" value="1" required></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Validate coupon</button></div></form></dialog>
